<script setup lang="ts">
import * as echarts from 'echarts/core'
import { LineChart, PieChart } from 'echarts/charts'
import { GridComponent, LegendComponent, TooltipComponent } from 'echarts/components'
import { CanvasRenderer } from 'echarts/renderers'
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import client from '../api/client'
import { chartAppearance } from '../composables/chartAppearance'
import { theme } from '../stores/theme'
import type { HistoryResponse } from '../api/monitorTypes'
import { loadSystemSettings, systemSettings } from '../stores/systemSettings'

echarts.use([LineChart, PieChart, GridComponent, LegendComponent, TooltipComponent, CanvasRenderer])

const root=ref<HTMLElement>(),trendEl=ref<HTMLElement>(),typeEl=ref<HTMLElement>(),data=ref<any>({states:{},latest_monitors:[],recent_incidents:[],probe_stats_24h:{}}),results=ref<any[]>([]),sla=ref<any[]>([]),now=ref(new Date()),updated=ref(''),connected=ref(false),error=ref(''),slaError=ref(false)
const periodHours=ref(12),periodRange=ref<{after:string;before:string}|null>(null),trendLoading=ref(false)
const periodOptions=[{hours:1,label:'近 1 小时'},{hours:6,label:'近 6 小时'},{hours:12,label:'近 12 小时'},{hours:24,label:'近 24 小时'},{hours:72,label:'近 3 天'},{hours:168,label:'近 7 天'},{hours:720,label:'近 1 个月'}]
let refreshPending=false
const rangeTime=(value:string)=>new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})
function changePeriod(){requestVersion++;results.value=[];periodRange.value=null;load()}
let trend:any,typeChart:any,timer:number|undefined,clock:number|undefined,socket:WebSocket|undefined,reconnectTimer:number|undefined,reloadTimer:number|undefined,requestVersion=0,stopped=false
const stateText:Record<string,string>={UP:'正常',DOWN:'故障',DEGRADED:'降级',MAINTENANCE:'维护',PAUSED:'暂停',PENDING:'待探测',UNKNOWN:'未知'}
const monitorMap=computed(()=>Object.fromEntries((data.value.latest_monitors||[]).map((m:any)=>[m.id,m])))
const healthy=computed(()=>data.value.health_rate==null?'—':Number(data.value.health_rate).toFixed(1))
const recentSuccess=computed(()=>results.value.length?(results.value.filter(r=>r.success).length/results.value.length*100).toFixed(1):'—')
const slowest=computed(()=>[...results.value].filter(r=>r.latency_ms!=null).sort((a,b)=>b.latency_ms-a.latency_ms).slice(0,5))
const fmtTime=(v:any)=>v?new Date(v).toLocaleTimeString('zh-CN',{hour12:false}):'--:--:--'
const color=(status:string)=>({UP:'#178665',DOWN:'#cb465b',DEGRADED:'#b97816',MAINTENANCE:'#2867dc',PENDING:'#78869b'}[status]||'#7d91ac')
function renderCharts(){
 if(!trendEl.value||!typeEl.value)return
 trend??=echarts.init(trendEl.value);typeChart??=echarts.init(typeEl.value)
 const appearance=chartAppearance(),grouped=new Map<string,any[]>()
 for(const r of [...results.value].reverse()){const points=grouped.get(r.monitor)||[];points.push([new Date(r.checked_at).getTime(),r.latency_ms]);grouped.set(r.monitor,points)}
 trend.setOption({...appearance,grid:{left:44,right:18,top:45,bottom:30},legend:{type:'scroll',top:0,bottom:'auto',textStyle:appearance.textStyle},tooltip:{...appearance.tooltip,trigger:'axis'},xAxis:{...appearance.xAxis,type:'time',min:periodRange.value?new Date(periodRange.value.after).getTime():undefined,max:periodRange.value?new Date(periodRange.value.before).getTime():undefined},yAxis:{...appearance.yAxis,type:'value',name:'ms'},series:[...grouped.entries()].map(([id,points])=>({name:monitorMap.value[id]?.name||id,type:'line',smooth:0.6,showSymbol:false,connectNulls:false,data:points,lineStyle:{width:2}}))},true)
 const counts:any={};for(const m of data.value.latest_monitors||[])counts[m.type]=(counts[m.type]||0)+1
 typeChart.setOption({animation:false,color:appearance.color,backgroundColor:appearance.backgroundColor,textStyle:appearance.textStyle,tooltip:{...appearance.tooltip,trigger:'item'},legend:{bottom:0,textStyle:appearance.textStyle},series:[{type:'pie',radius:['50%','72%'],center:['50%','43%'],label:{show:false},itemStyle:{borderColor:theme.value==='dark'?'#182335':'#ffffff',borderWidth:3,borderRadius:3},data:Object.entries(counts).map(([name,value],i)=>({name,value,itemStyle:{color:appearance.color[i%appearance.color.length]}}))}]},true)
}
watch(theme,()=>renderCharts())
async function load(){
 if(stopped)return
 if(trendLoading.value){refreshPending=true;return}
 trendLoading.value=true
 const version=++requestVersion,before=new Date(),after=new Date(before.getTime()-periodHours.value*3600000)
 try{
  const [summary,history,slaReport]=await Promise.all([
   client.get('/dashboard/summary/'),
   client.get<HistoryResponse>('/monitors/history/',{params:{checked_after:after.toISOString(),checked_before:before.toISOString(),page_size:1},timeout:60000}),
   client.get('/reports/sla/',{params:{days:1}}).then(response=>({...response,unavailable:false})).catch(()=>({data:{results:[]},unavailable:true}))
  ])
  if(stopped||version!==requestVersion)return
  data.value=summary.data
  results.value=history.data.series.map(point=>({id:point.id,monitor:point.monitor,checked_at:point.at,latency_ms:point.latency_ms,success:point.success})).reverse()
  periodRange.value={after:history.data.checked_after,before:history.data.checked_before}
  sla.value=slaReport.data.results||[];slaError.value=slaReport.unavailable
  updated.value=fmtTime(summary.data.snapshot_at||new Date());error.value=''
  await nextTick();renderCharts()
 }catch(e:any){if(!stopped&&version===requestVersion)error.value=e.response?.data?.message||'数据连接异常'}
 finally{trendLoading.value=false;if(refreshPending&&!stopped){refreshPending=false;load()}}
}

function scheduleLoad(){if(stopped||reloadTimer)return;reloadTimer=window.setTimeout(()=>{reloadTimer=undefined;load()},250)}
function connect(){const token=localStorage.getItem('access_token');if(!token||stopped)return;const scheme=location.protocol==='https:'?'wss':'ws';socket=new WebSocket(`${scheme}://${location.host}/ws/v1/status/?token=${encodeURIComponent(token)}`);socket.onopen=()=>{connected.value=true;if(reconnectTimer)clearTimeout(reconnectTimer)};socket.onclose=()=>{connected.value=false;if(!stopped)reconnectTimer=window.setTimeout(connect,3000)};socket.onerror=()=>socket?.close();socket.onmessage=(event)=>{try{const message=JSON.parse(event.data);if(message.type==='monitor.result')scheduleLoad()}catch{scheduleLoad()}}}
function toggleFull(){document.fullscreenElement?document.exitFullscreen():root.value?.requestFullscreen()}
function resize(){trend?.resize();typeChart?.resize()}
onMounted(async()=>{stopped=false;load();connect();try{await loadSystemSettings()}catch{systemSettings.monitor_wall_refresh_seconds=10}if(stopped)return;timer=window.setInterval(load,Math.max(5,Number(systemSettings.monitor_wall_refresh_seconds)||10)*1000);clock=window.setInterval(()=>now.value=new Date(),1000);window.addEventListener('resize',resize)})
onBeforeUnmount(()=>{stopped=true;requestVersion++;if(timer)clearInterval(timer);if(clock)clearInterval(clock);if(reconnectTimer)clearTimeout(reconnectTimer);if(reloadTimer)clearTimeout(reloadTimer);socket?.close();trend?.dispose();typeChart?.dispose();window.removeEventListener('resize',resize)})
</script>

<template><div ref="root" class="wall" v-loading="trendLoading&&!updated" :aria-busy="trendLoading&&!updated">
  <div class="grid-bg"></div><header><div class="header-side"><span class="signal" :class="{on:connected}"><i/>{{connected?'实时链路 ONLINE':'定时同步'}}</span></div><div class="title"><i></i><div><h1>{{systemSettings.monitor_wall_title}}</h1><p>HELI DATA · BUSINESS OBSERVABILITY COMMAND CENTER</p></div><i></i></div><div class="header-side right"><button @click="toggleFull">⛶ 全屏</button><div class="clock"><b>{{now.toLocaleTimeString('zh-CN',{hour12:false})}}</b><span>{{now.toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'})}}</span></div></div></header>
  <div v-if="error" class="error-banner">{{error}}</div>
  <main>
    <section class="kpis panel"><div class="kpi"><span>业务系统</span><b>{{data.businesses_total||0}}</b><small>BUSINESS</small></div><div class="kpi"><span>监控任务</span><b>{{data.monitors_total||0}}</b><small>MONITORS</small></div><div class="kpi healthy"><span>整体健康度</span><b>{{healthy}}<em v-if="healthy!=='—'">%</em></b><small>HEALTH INDEX</small></div><div class="kpi"><span>24H 探测</span><b>{{data.probe_stats_24h?.total||0}}</b><small>PROBES</small></div><div class="kpi success"><span>24H 成功率</span><b>{{data.probe_stats_24h?.success_rate??'—'}}<em>%</em></b><small>SUCCESS RATE</small></div><div class="kpi alarm"><span>24H 失败</span><b>{{data.probe_stats_24h?.failed||0}}</b><small>FAILED PROBES</small></div><div class="kpi"><span>平均响应</span><b>{{data.probe_stats_24h?.average_latency_ms==null?'—':Number(data.probe_stats_24h.average_latency_ms).toFixed(1)}}<em>ms</em></b><small>AVG LATENCY</small></div><div class="kpi alarm"><span>开放事件</span><b>{{data.open_incidents||0}}</b><small>TODAY {{data.today_incidents||0}}</small></div></section>
    <div class="dashboard-grid">
      <div class="left-col"><section class="panel block"><h2><span>监控状态矩阵</span><small>STATUS MATRIX</small></h2><div class="state-matrix"><div v-for="s in ['UP','DOWN','DEGRADED','MAINTENANCE','PAUSED','PENDING','UNKNOWN']" :key="s"><i :style="{background:color(s),boxShadow:`0 0 12px ${color(s)}`}"/><span>{{stateText[s]}}</span><b>{{data.states?.[s]||0}}</b></div></div></section><section class="panel block type-block"><h2><span>探测类型分布</span><small>PROBE TYPES</small></h2><div ref="typeEl" class="chart"></div></section></div>
      <div class="center-col"><section class="panel block trend-block"><h2><span>实时响应趋势</span><select v-model.number="periodHours" aria-label="响应趋势时间周期" class="period-select" @change="changePeriod"><option v-for="option in periodOptions" :key="option.hours" :value="option.hours">{{option.label}}</option></select></h2><div class="period-range">{{trendLoading?'正在加载周期数据…':'周期内 '+results.length+' 个原始数据点'}}<span v-if="periodRange"> · {{rangeTime(periodRange.after)}} — {{rangeTime(periodRange.before)}}</span></div><div ref="trendEl" class="trend-chart"></div></section><section class="panel block topology"><h2><span>业务健康拓扑</span><small>LIVE MONITOR NODES</small></h2><div class="nodes"><div v-for="m in data.latest_monitors" :key="m.id" class="node" :class="m.status.toLowerCase()"><span class="pulse"></span><b>{{m.name}}</b><small>{{m.type}} · {{m.latency_ms==null?'—':m.latency_ms+' ms'}}</small></div></div></section></div>
      <div class="right-col"><section class="panel block event-block"><h2><span>实时事件</span><small>ACTIVE INCIDENTS</small></h2><div v-if="!data.recent_incidents?.length" class="all-clear"><div>✓</div><b>当前无开放事件</b><span>ALL SYSTEMS OPERATIONAL</span></div><div v-else class="events"><div v-for="i in data.recent_incidents" :key="i.id"><span :class="i.severity.toLowerCase()">{{i.severity}}</span><b>{{i.title}}</b><small>{{i.business}} · {{fmtTime(i.opened_at)}}</small></div></div></section><section class="panel block stream-block"><h2><span>实时探测流</span><small>LIVE PROBE STREAM</small></h2><div class="stream"><div v-for="r in results.slice(0,9)" :key="r.id"><i :class="r.success?'ok':'fail'"/><span>{{monitorMap[r.monitor]?.name||'探测任务'}}</span><em>{{r.latency_ms==null?'—':r.latency_ms+' ms'}}</em><small>{{fmtTime(r.checked_at)}}</small></div></div></section></div>
    </div>
    <div class="intel-grid">
      <section class="panel block sla-block"><h2><span>24H SLA 可用率</span><small>BUSINESS SERVICE LEVEL</small></h2><div v-if="slaError" role="status">SLA 数据不可用或无报表查看权限</div><div v-else-if="!sla.length">暂无 SLA 数据</div><div class="sla-list"><div v-for="s in sla.slice(0,8)" :key="s.monitor_id"><div><b>{{s.monitor_name}}</b><small>{{s.business_name}} · {{s.samples}} 个样本</small></div><span :class="Number(s.availability)<99?'warn':''">{{s.availability==null?'—':Number(s.availability).toFixed(3)+'%'}}</span><em><i :style="{width:(s.availability||0)+'%'}"/></em></div></div></section>
      <section class="panel block inventory-block"><h2><span>全量监控清单</span><small>ALL ACTIVE MONITORS</small></h2><div class="inventory"><div v-for="m in data.latest_monitors" :key="m.id"><i :style="{background:color(m.status)}"/><span><b>{{m.name}}</b><small>{{m.business}}</small></span><em>{{m.type}}</em><strong>{{stateText[m.status]||m.status}}</strong><small>{{m.latency_ms==null?'—':m.latency_ms+' ms'}}</small></div></div></section>
      <section class="panel block perf-block"><h2><span>性能热点 TOP 5</span><small>SLOWEST RECENT PROBES</small></h2><div class="slow-list"><div v-for="(r,index) in slowest" :key="r.id"><b>0{{index+1}}</b><span>{{monitorMap[r.monitor]?.name||'探测任务'}}</span><em>{{Number(r.latency_ms).toFixed(2)}} ms</em></div></div><div class="sample-rate"><span>周期内 {{results.length}} 个样本成功率</span><b>{{recentSuccess}}%</b></div></section>
    </div>
  </main><footer><span>服务端快照 {{updated||'--:--:--'}}</span><b>HELI MONITOR · 全域业务可用性监控</b><span>实时推送 · 10s 兜底同步</span></footer>
</div></template>

<style scoped>
.wall{--cyan:var(--brand);--green:var(--success);--line:var(--border);position:relative;min-height:calc(100dvh - 140px);padding:0;color:var(--text-primary);background:var(--canvas);min-width:0}.wall:fullscreen{padding:20px;overflow:auto;background:var(--canvas)}.grid-bg{display:none}header{display:grid;grid-template-columns:1fr 2fr 1fr;align-items:center;gap:12px;padding:0 0 20px;min-height:82px}.title{text-align:center}.title i{display:none}h1{font-size:24px;letter-spacing:-.03em;margin:0;color:var(--text-primary)}.title p{font-size:9px;letter-spacing:.18em;color:var(--muted);margin:5px 0 0}.header-side.right{display:flex;align-items:center;justify-content:flex-end;gap:14px}.signal{font-size:11px;color:var(--muted);display:flex;align-items:center;gap:7px}.signal i{width:6px;height:6px;border-radius:50%;background:var(--muted)}.signal.on{color:var(--success)}.signal.on i{background:var(--success)}header button{color:var(--text-secondary);background:var(--surface);border:1px solid var(--border);padding:7px 12px;cursor:pointer;border-radius:7px;font-size:11px}.clock{display:flex;flex-direction:column;align-items:flex-end}.clock b{font:600 18px 'Segoe UI',sans-serif;font-variant-numeric:tabular-nums;color:var(--text-primary)}.clock span{font-size:10px;color:var(--muted)}.error-banner{padding:10px 14px;color:var(--danger);background:var(--danger-soft);border:1px solid var(--danger);border-radius:8px;margin-bottom:14px}.panel{background:var(--surface);border:1px solid var(--border);border-radius:12px;min-width:0;overflow:hidden}.kpis{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));margin-bottom:18px}.kpi{padding:18px 10px;border-right:1px solid var(--divider);text-align:center;min-width:0}.kpi:last-child{border:0}.kpi span,.kpi small{display:block;color:var(--muted);font-size:11px}.kpi small{font-size:8px;letter-spacing:.08em}.kpi b{display:block;color:var(--text-primary);font:650 28px 'Segoe UI',sans-serif;letter-spacing:-.035em;font-variant-numeric:tabular-nums;margin:8px 0}.kpi em{font-size:13px;font-style:normal}.kpi.healthy b,.kpi.success b{color:var(--success)}.kpi.alarm b{color:var(--danger)}.dashboard-grid{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.7fr) minmax(0,1fr);gap:16px;min-height:610px}.left-col,.center-col,.right-col{display:grid;gap:16px;min-width:0}.left-col{grid-template-rows:1fr 1.1fr}.center-col{grid-template-rows:1.1fr 1fr}.right-col{grid-template-rows:.9fr 1.2fr}.block{padding:18px;min-height:0}.block h2{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:0 0 15px;padding-bottom:12px;border-bottom:1px solid var(--divider);font-size:13px;font-weight:650;color:var(--text-primary)}.block h2 small{color:var(--muted);font-size:8px;font-weight:400;letter-spacing:.06em}.state-matrix{display:grid;gap:5px}.state-matrix>div{display:grid;grid-template-columns:10px 1fr 30px;align-items:center;padding:8px 10px;background:var(--surface-subtle);border-radius:6px;gap:8px}.state-matrix i{width:6px;height:6px;border-radius:50%}.state-matrix span{font-size:11px;color:var(--text-secondary)}.state-matrix b{font-size:15px;text-align:right;font-variant-numeric:tabular-nums}.chart,.trend-chart{width:100%;height:calc(100% - 40px);min-height:200px}.nodes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.node{position:relative;padding:12px 10px 12px 24px;background:var(--surface-subtle);border:1px solid var(--border);border-radius:8px;min-width:0}.node b,.node small{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.node b{font-size:11px;font-weight:550}.node small{font-size:9px;color:var(--muted);margin-top:5px}.pulse{position:absolute;left:10px;top:18px;width:6px;height:6px;border-radius:50%;background:var(--muted)}.node.up .pulse{background:var(--success)}.node.down{border-color:var(--danger);background:var(--danger-soft)}.node.down .pulse{background:var(--danger)}.node.degraded .pulse{background:var(--warning)}.all-clear{height:calc(100% - 40px);min-height:130px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px}.all-clear div{width:46px;height:46px;border-radius:50%;background:var(--success-soft);color:var(--success);display:grid;place-items:center;font-size:24px}.all-clear b{font-size:12px;color:var(--success)}.all-clear span{font-size:8px;letter-spacing:.12em;color:var(--muted)}.events>div{display:grid;grid-template-columns:58px 1fr;gap:5px;padding:10px 0;border-bottom:1px solid var(--divider)}.events span{font-size:9px;color:var(--danger)}.events b{font-size:11px}.events small{grid-column:2;color:var(--muted);font-size:9px}.stream{display:grid}.stream>div{display:grid;grid-template-columns:8px minmax(0,1fr) 62px 58px;align-items:center;gap:6px;padding:9px 0;border-bottom:1px solid var(--divider);font-size:10px}.stream i{width:6px;height:6px;border-radius:50%}.stream i.ok{background:var(--success)}.stream i.fail{background:var(--danger)}.stream span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--text-secondary)}.stream em{color:var(--brand);font-style:normal;text-align:right}.stream small{color:var(--muted);text-align:right}.period-select{background:var(--surface-subtle);color:var(--text-secondary);border:1px solid var(--border);border-radius:6px;padding:4px 6px;font-size:10px;max-width:110px}.period-range{font-size:10px;color:var(--muted);margin:0 0 8px}.intel-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.5fr) minmax(0,1fr);gap:16px;margin-top:16px;min-height:260px}.sla-list{display:grid;gap:6px}.sla-list>div{display:grid;grid-template-columns:minmax(0,1fr) 72px;align-items:center;padding:6px 0;gap:4px}.sla-list b,.sla-list small{display:block}.sla-list b{font-size:11px;font-weight:550}.sla-list small{font-size:9px;color:var(--muted);margin-top:3px}.sla-list span{text-align:right;color:var(--success);font-size:12px;font-variant-numeric:tabular-nums}.sla-list span.warn{color:var(--warning)}.sla-list em{grid-column:1/-1;height:3px;background:var(--divider);margin-top:3px;overflow:hidden;border-radius:3px}.sla-list em i{display:block;height:100%;max-width:100%;background:var(--success)}.inventory{display:grid;gap:6px;max-height:270px;overflow:auto}.inventory>div{display:grid;grid-template-columns:8px minmax(0,1fr) 56px 44px 66px;align-items:center;gap:6px;padding:8px;background:var(--surface-subtle);border-radius:6px}.inventory>div>i{width:6px;height:6px;border-radius:50%}.inventory span b,.inventory span small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.inventory span b{font-size:10px;font-weight:550}.inventory span small,.inventory>div>small{font-size:9px;color:var(--muted)}.inventory em,.inventory strong{font-size:9px;font-style:normal;font-weight:500;color:var(--text-secondary)}.slow-list{display:grid;gap:6px}.slow-list>div{display:grid;grid-template-columns:24px minmax(0,1fr) 76px;align-items:center;gap:6px;padding:10px;background:var(--surface-subtle);border-radius:6px}.slow-list b{font-size:12px;color:var(--muted)}.slow-list span{font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.slow-list em{font-size:10px;color:var(--warning);font-style:normal;text-align:right}.sample-rate{display:flex;justify-content:space-between;gap:8px;margin-top:12px;padding:12px 0 0;border-top:1px solid var(--divider);color:var(--muted);font-size:10px}.sample-rate b{color:var(--success);font-size:14px}footer{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:18px 0 0;color:var(--muted);font-size:9px}footer b{font-weight:500;letter-spacing:.04em}
@media(min-width:1900px){.wall{font-size:14px}.kpi b{font-size:34px}.dashboard-grid{min-height:720px}.block h2{font-size:15px}.nodes .node{padding-top:16px;padding-bottom:16px}}
@media(max-width:1300px){.dashboard-grid{grid-template-columns:minmax(0,1fr) minmax(0,1.6fr)}.right-col{grid-column:1/-1;grid-template-columns:1fr 1fr;grid-template-rows:auto}.intel-grid{grid-template-columns:1fr 1fr}.perf-block{grid-column:1/-1}.kpis{grid-template-columns:repeat(4,1fr)}.kpi:nth-child(4){border-right:0}.kpi:nth-child(-n+4){border-bottom:1px solid var(--divider)}.nodes{grid-template-columns:repeat(2,minmax(0,1fr))}.title h1{font-size:21px}.block h2 small{display:none}}
@media(max-width:700px){header{grid-template-columns:1fr auto}.title{grid-column:1/-1;grid-row:1;text-align:left}.title h1{font-size:20px}.header-side.right{gap:10px}.clock b{font-size:14px}.kpi{padding:12px 6px}.kpi b{font-size:23px}.kpi small{display:none}.kpis{margin-top:8px}.dashboard-grid,.intel-grid{grid-template-columns:1fr}.left-col{grid-template-rows:auto 260px}.center-col{grid-template-rows:auto 320px}.right-col{grid-template-columns:1fr;grid-template-rows:200px auto}.perf-block{grid-column:auto}.nodes{grid-template-columns:repeat(2,minmax(0,1fr))}.block{padding:16px}.chart,.trend-chart{min-height:200px}footer{flex-wrap:wrap;justify-content:center}.inventory{max-height:330px}}
</style>



